%[text] # **Adaptive transient analysis of a nonlinear viscous-damper frame**
%[text] Compare fixed substepping with two adaptive solutions of a nonlinear
%[text] viscous-damper frame. Failed attempts are retained in the convergence
%[text] history so the recovery process remains visible. Units are mm, kN, and s.
clear;
clc;
close all;
%%
%[text] ## Input and analysis parameters
gmFile = fullfile("TakY.th");

if ~isfile(gmFile)
    error('Ground-motion file not found: "%s".', gmFile);
end

dtGM = 0.01;
dtReference = 0.001;

gravityAcceleration = 9810.0;

% The original benchmark uses 0.50g. The multiplier raises the nominal
% excitation to 5.00g to produce a demanding nonlinear response.
benchmarkScale = 0.50;
intensityFactor = 10.0;

excitationScale = ...
    benchmarkScale * intensityFactor * gravityAcceleration;

groundMotion = load(gmFile);
groundMotion = groundMotion(isfinite(groundMotion));

if isempty(groundMotion)
    error('No valid acceleration samples were found in "%s".', gmFile);
end

duration = numel(groundMotion) * dtGM;
nOuter = numel(groundMotion);
nReference = round(duration/dtReference);

fprintf("Nonlinear viscous-damper frame\n"); %[output:174d38d4]
fprintf("--------------------------------------------------\n"); %[output:667436e5]
fprintf("Ground-motion samples : %d\n", numel(groundMotion)); %[output:59a9fa17]
fprintf("Excitation level      : %.2f g\n", ... %[output:group:90f8cee1] %[output:8ef072eb]
    excitationScale/gravityAcceleration); %[output:group:90f8cee1] %[output:8ef072eb]
fprintf("Duration              : %.3f s\n", duration); %[output:4ad10b17]
fprintf("Reference time step   : %.6f s\n", dtReference); %[output:6d3b4fe9]
fprintf("Adaptive time step    : %.6f s (ground-motion dt)\n\n", dtGM); %[output:337931da]
%%
%[text] ## Output locations

resultRoot = fullfile("AdaptiveDamperResults");
referenceDir = fullfile(resultRoot, "Substepped");
adaptiveDir = fullfile(resultRoot, "Adaptive");
adaptiveFineDir = fullfile(resultRoot, "AdaptiveFine");
figureDir = fullfile("figures");

directories = {
    resultRoot
    referenceDir
    adaptiveDir
    adaptiveFineDir
    figureDir
};

for i = 1:numel(directories)
    if ~isfolder(directories{i})
        mkdir(directories{i});
    end
end

adaptiveLog = fullfile(adaptiveDir, "adaptive_history.csv");
staleAdaptiveFineLog = fullfile(adaptiveFineDir, "adaptive_history.csv");

% Remove the previous log because older versions may use different columns.
if isfile(adaptiveLog)
    delete(adaptiveLog);
end
if isfile(staleAdaptiveFineLog)
    delete(staleAdaptiveFineLog);
end
%%
%[text] ## Create the OpenSeesMatlab interface
opsMAT = OpenSeesMatlab();
ops = opsMAT.opensees;
%%
%[text] ## Fine-substep analysis
fprintf("Running fine-substep analysis...\n"); %[output:91acc286]

reference = runAnalysis( ...
    ops, ...
    gmFile, ...
    dtGM, ...
    excitationScale, ...
    "reference", ...
    nReference, ...
    dtReference, ...
    referenceDir, ...
    "");

if reference.code ~= 0
    error( ...
        "Fine-substep analysis failed at t = %.6f s.", ...
        reference.endTime);
end
%%
%[text] ## Adaptive transient analysis
fprintf("Running adaptive analysis...\n"); %[output:63b678e2]

adaptive = runAnalysis( ... %[output:group:04eccbeb] %[output:1addfeef]
    ops, ... %[output:1addfeef]
    gmFile, ... %[output:1addfeef]
    dtGM, ... %[output:1addfeef]
    excitationScale, ... %[output:1addfeef]
    "adaptive", ... %[output:1addfeef]
    nOuter, ... %[output:1addfeef]
    dtGM, ... %[output:1addfeef]
    adaptiveDir, ... %[output:1addfeef]
    adaptiveLog); %[output:group:04eccbeb] %[output:1addfeef]

if adaptive.code ~= 0
    error( ...
        "Adaptive analysis failed at t = %.6f s.", ...
        adaptive.endTime);
end
%%
%[text] ## Adaptive analysis at the reference time step
fprintf("Running adaptive analysis at the fine reference time step...\n"); %[output:6a8e70b5]

adaptiveFine = runAnalysis( ... %[output:group:814ba96b] %[output:70b39858]
    ops, ... %[output:70b39858]
    gmFile, ... %[output:70b39858]
    dtGM, ... %[output:70b39858]
    excitationScale, ... %[output:70b39858]
    "adaptive_fine", ... %[output:70b39858]
    nReference, ... %[output:70b39858]
    dtReference, ... %[output:70b39858]
    adaptiveFineDir, ... %[output:70b39858]
    ""); %[output:group:814ba96b] %[output:70b39858]

if adaptiveFine.code ~= 0
    error( ...
        "Fine-step adaptive analysis failed at t = %.6f s.", ...
        adaptiveFine.endTime);
end
%%
%[text] ## Compare responses at common physical times
%[text] Adaptive recovery may introduce internal substeps. Interpolation at the
%[text] requested outer times ensures that all solutions are compared at the same
%[text] physical instants.

targetTime = (0:nOuter).' * dtGM;
fineTargetTime = (0:nReference).' * dtReference;

referenceAtTarget = interpolateResponse( ...
    reference, targetTime);

adaptiveAtTarget = interpolateResponse( ...
    adaptive, targetTime);

referenceAtFineTarget = interpolateResponse( ...
    reference, fineTargetTime);

adaptiveFineAtTarget = interpolateResponse( ...
    adaptiveFine, fineTargetTime);

referencePeak = max(abs(reference.displacement));

adaptivePeak = max(abs( ...
    adaptiveAtTarget.displacement));

adaptiveFinePeak = max(abs( ...
    adaptiveFineAtTarget.displacement));

adaptiveError = ...
    adaptiveAtTarget.displacement - ...
    referenceAtTarget.displacement;

adaptiveFineError = ...
    adaptiveFineAtTarget.displacement - ...
    referenceAtFineTarget.displacement;

adaptiveNRMSE = sqrt(mean(adaptiveError.^2)) / ...
    max(referencePeak, eps);

adaptiveFineNRMSE = sqrt(mean(adaptiveFineError.^2)) / ...
    max(referencePeak, eps);

adaptivePeakError = ...
    abs(adaptivePeak - referencePeak) / ...
    max(referencePeak, eps);

adaptiveFinePeakError = ...
    abs(adaptiveFinePeak - referencePeak) / ...
    max(referencePeak, eps);

maximumAbsoluteDifference = max(abs(adaptiveError));
maximumRelativeDifference = 100.0 * maximumAbsoluteDifference / ...
    max(referencePeak, eps);

maximumFineAbsoluteDifference = max(abs(adaptiveFineError));
maximumFineRelativeDifference = 100.0 * maximumFineAbsoluteDifference / ...
    max(referencePeak, eps);

% Evaluate both force-deformation histories at exactly the same physical
% times before integrating, so the energy difference is not contaminated
% by unequal recorder sampling intervals.
referenceEnergy = abs(trapz( ...
    referenceAtTarget.damperDeformation, ...
    referenceAtTarget.damperForce));
adaptiveEnergy = abs(trapz( ...
    adaptiveAtTarget.damperDeformation, ...
    adaptiveAtTarget.damperForce));
energyDifference = abs(adaptiveEnergy - referenceEnergy);
relativeEnergyDifference = 100.0 * energyDifference / ...
    max(referenceEnergy, eps);

referenceFineEnergy = abs(trapz( ...
    referenceAtFineTarget.damperDeformation, ...
    referenceAtFineTarget.damperForce));
adaptiveFineEnergy = abs(trapz( ...
    adaptiveFineAtTarget.damperDeformation, ...
    adaptiveFineAtTarget.damperForce));
fineEnergyDifference = abs(adaptiveFineEnergy - referenceFineEnergy);
relativeFineEnergyDifference = 100.0 * fineEnergyDifference / ...
    max(referenceFineEnergy, eps);
%%
%[text] ## Summary table

method = [
    "Reference, fine dt"
    "Adaptive, ground-motion dt"
    "Adaptive, fine dt"
];

returnCode = [
    reference.code
    adaptive.code
    adaptiveFine.code
];

completedTime = [
    reference.endTime
    adaptive.endTime
    adaptiveFine.endTime
];

nominalStep = [
    dtReference
    dtGM
    dtReference
];

requestedSteps = [
    nReference
    nOuter
    nReference
];
runtime = [
    reference.runtime
    adaptive.runtime
    adaptiveFine.runtime
];

peakDisplacement = [
    referencePeak
    adaptivePeak
    adaptiveFinePeak
];

normalizedRMSE = [
    0.0
    adaptiveNRMSE
    adaptiveFineNRMSE
];

relativePeakError = [
    0.0
    adaptivePeakError
    adaptiveFinePeakError
];

maximumRelativeDifferencePct = [
    0.0
    maximumRelativeDifference
    maximumFineRelativeDifference
];

relativeEnergyDifferencePct = [
    0.0
    relativeEnergyDifference
    relativeFineEnergyDifference
];

summaryTable = table( ...
    method, ...
    returnCode, ...
    completedTime, ...
    nominalStep, ...
    requestedSteps, ...
    runtime, ...
    peakDisplacement, ...
    normalizedRMSE, ...
    relativePeakError, ...
    maximumRelativeDifferencePct, ...
    relativeEnergyDifferencePct, ...
    VariableNames=[ ...
        "Method", ...
        "ReturnCode", ...
        "EndPhysicalTime_s", ...
        "NominalStep_s", ...
        "RequestedSteps", ...
        "WallClockTime_s", ...
        "PeakDisplacement_mm", ...
        "NormalizedRMSE", ...
        "RelativePeakError", ...
        "MaxRelativeDifference_pct", ...
        "RelativeEnergyDifference_pct"]);

fprintf("\nAnalysis summary\n"); %[output:0fe9ad3c]
fprintf("============================================================\n"); %[output:2cd6a341]
disp(summaryTable); %[output:53dc640d]
fprintf("\nEndPhysicalTime_s matches because all cases cover the same earthquake record.\n"); %[output:7a4c0c9b]
fprintf("Compare RequestedSteps and WallClockTime_s for computational cost.\n"); %[output:3d5dd095]

writetable( ...
    summaryTable, ...
    fullfile(resultRoot, "analysis_summary.csv"));
%%
%[text] ## Roof-displacement comparison

figure1 = figure( ... %[output:8f303923]
    Color="w", ... %[output:8f303923]
    Position=[80, 80, 1000, 560]); %[output:8f303923]

ax1 = axes(figure1); %[output:8f303923]
hold(ax1, "on"); %[output:8f303923]
box(ax1, "on"); %[output:8f303923]
grid(ax1, "on"); %[output:8f303923]

plot(ax1, ... %[output:8f303923]
    reference.time, ... %[output:8f303923]
    reference.displacement, ... %[output:8f303923]
    Color=[0.10, 0.10, 0.10], ... %[output:8f303923]
    LineWidth=2, ... %[output:8f303923]
    DisplayName="Reference"); %[output:8f303923]

plot(ax1, ... %[output:8f303923]
    adaptive.time, ... %[output:8f303923]
    adaptive.displacement, ... %[output:8f303923]
    "--", ... %[output:8f303923]
    Color=[0.80, 0.20, 0.15], ... %[output:8f303923]
    LineWidth=2, ... %[output:8f303923]
    DisplayName="Adaptive (0.01 s)"); %[output:8f303923]

plot(ax1, ... %[output:8f303923]
    adaptiveFine.time, ... %[output:8f303923]
    adaptiveFine.displacement, ... %[output:8f303923]
    ":", ... %[output:8f303923]
    Color=[0.00, 0.35, 0.70], ... %[output:8f303923]
    LineWidth=2, ... %[output:8f303923]
    DisplayName="Adaptive (0.001 s)"); %[output:8f303923]

xlabel(ax1, "Time (s)", Interpreter="none"); %[output:8f303923]
ylabel(ax1, "Roof displacement (mm)", Interpreter="none"); %[output:8f303923]

roofText = sprintf( ...
    "Max. relative difference: 0.01 s = %.4f%%; 0.001 s = %.4f%%", ...
    maximumRelativeDifference, maximumFineRelativeDifference);

roofValues = [reference.displacement; adaptive.displacement; ...
    adaptiveFine.displacement];
roofRange = max(roofValues) - min(roofValues);
ylim(ax1, [min(roofValues) - 0.12*roofRange, ... %[output:8f303923]
    max(roofValues) + 0.18*roofRange]); %[output:8f303923]

text(ax1, 0.02, 0.97, roofText, Units="normalized", ... %[output:8f303923]
    VerticalAlignment="top", Interpreter="none", FontSize=15, ... %[output:8f303923]
    BackgroundColor="w", Margin=3); %[output:8f303923]

legend(ax1, ... %[output:8f303923]
    Location="southeast", ... %[output:8f303923]
    Orientation="horizontal", ... %[output:8f303923]
    NumColumns=3, ... %[output:8f303923]
    Box="on", ... %[output:8f303923]
    Color="white", ... %[output:8f303923]
    EdgeColor=[0.35 0.35 0.35], ... %[output:8f303923]
    Interpreter="none", ... %[output:8f303923]
    FontSize=15); %[output:8f303923]

stylePaperAxes(ax1); %[output:8f303923]

exportgraphics( ... %[output:group:4903ac53] %[output:8f303923]
    figure1, ... %[output:8f303923]
    fullfile(figureDir, ... %[output:8f303923]
    "adaptive_analysis_roof_displacement_comparison.pdf"), ... %[output:8f303923]
    ContentType="vector"); %[output:group:4903ac53] %[output:8f303923]

roofFigureData = [ ...
    table(repmat("Reference", numel(reference.time), 1), ...
        reference.time, reference.displacement, ...
        'VariableNames', {'Method','Time_s','RoofDisplacement_mm'}); ...
    table(repmat("Adaptive_0.01_s", numel(adaptive.time), 1), ...
        adaptive.time, adaptive.displacement, ...
        'VariableNames', {'Method','Time_s','RoofDisplacement_mm'}); ...
    table(repmat("Adaptive_0.001_s", numel(adaptiveFine.time), 1), ...
        adaptiveFine.time, adaptiveFine.displacement, ...
        'VariableNames', {'Method','Time_s','RoofDisplacement_mm'})];
writetable(roofFigureData, fullfile(figureDir, ...
    "adaptive_analysis_roof_displacement_comparison.csv"));
%%
%[text] ## Damper force-deformation comparison

figure2 = figure( ... %[output:1d1089a4]
    Color="w", ... %[output:1d1089a4]
    Position=[120, 80, 820, 650]); %[output:1d1089a4]

ax2 = axes(figure2); %[output:1d1089a4]
hold(ax2, "on"); %[output:1d1089a4]
box(ax2, "on"); %[output:1d1089a4]
grid(ax2, "on"); %[output:1d1089a4]

plot(ax2, ... %[output:1d1089a4]
    reference.damperDeformation, ... %[output:1d1089a4]
    reference.damperForce, ... %[output:1d1089a4]
    Color=[0.10, 0.10, 0.10], ... %[output:1d1089a4]
    LineWidth=2, ... %[output:1d1089a4]
    DisplayName="Reference"); %[output:1d1089a4]

plot(ax2, ... %[output:1d1089a4]
    adaptive.damperDeformation, ... %[output:1d1089a4]
    adaptive.damperForce, ... %[output:1d1089a4]
    "--", ... %[output:1d1089a4]
    Color=[0.80, 0.20, 0.15], ... %[output:1d1089a4]
    LineWidth=2, ... %[output:1d1089a4]
    DisplayName="Adaptive (0.01 s)"); %[output:1d1089a4]

plot(ax2, ... %[output:1d1089a4]
    adaptiveFine.damperDeformation, ... %[output:1d1089a4]
    adaptiveFine.damperForce, ... %[output:1d1089a4]
    ":", ... %[output:1d1089a4]
    Color=[0.00, 0.35, 0.70], ... %[output:1d1089a4]
    LineWidth=2, ... %[output:1d1089a4]
    DisplayName="Adaptive (0.001 s)"); %[output:1d1089a4]

xline(ax2, 0, ":", HandleVisibility="off"); %[output:1d1089a4]
yline(ax2, 0, ":", HandleVisibility="off"); %[output:1d1089a4]

xlabel(ax2, "Damper deformation (mm)", Interpreter="none"); %[output:1d1089a4]
ylabel(ax2, "Damper force (kN)", Interpreter="none"); %[output:1d1089a4]
energyText = sprintf( ...
    "Relative energy difference: 0.01 s = %.4f%%; 0.001 s = %.4f%%", ...
    relativeEnergyDifference, relativeFineEnergyDifference);

forceValues = [reference.damperForce; adaptive.damperForce; ...
    adaptiveFine.damperForce];
forceRange = max(forceValues) - min(forceValues);
ylim(ax2, [min(forceValues) - 0.20*forceRange, ... %[output:1d1089a4]
    max(forceValues) + 0.18*forceRange]); %[output:1d1089a4]

text(ax2, 0.02, 0.97, energyText, Units="normalized", ... %[output:1d1089a4]
    VerticalAlignment="top", Interpreter="none", FontSize=15, ... %[output:1d1089a4]
    BackgroundColor="w", Margin=3); %[output:1d1089a4]

legend(ax2, ... %[output:1d1089a4]
    Location="southeast", ... %[output:1d1089a4]
    Orientation="horizontal", ... %[output:1d1089a4]
    NumColumns=3, ... %[output:1d1089a4]
    Box="on", ... %[output:1d1089a4]
    Color="white", ... %[output:1d1089a4]
    EdgeColor=[0.35 0.35 0.35], ... %[output:1d1089a4]
    Interpreter="none", ... %[output:1d1089a4]
    FontSize=15); %[output:1d1089a4]

stylePaperAxes(ax2); %[output:1d1089a4]

exportgraphics( ... %[output:group:8ad2676e] %[output:1d1089a4]
    figure2, ... %[output:1d1089a4]
    fullfile(figureDir, ... %[output:1d1089a4]
    "adaptive_analysis_damper_hysteresis_comparison.pdf"), ... %[output:1d1089a4]
    ContentType="vector"); %[output:group:8ad2676e] %[output:1d1089a4]

damperFigureData = [ ...
    table(repmat("Reference", numel(reference.damperForce), 1), ...
        reference.damperDeformation, reference.damperForce, ...
        'VariableNames', {'Method','Deformation_mm','Force_kN'}); ...
    table(repmat("Adaptive_0.01_s", numel(adaptive.damperForce), 1), ...
        adaptive.damperDeformation, adaptive.damperForce, ...
        'VariableNames', {'Method','Deformation_mm','Force_kN'}); ...
    table(repmat("Adaptive_0.001_s", numel(adaptiveFine.damperForce), 1), ...
        adaptiveFine.damperDeformation, adaptiveFine.damperForce, ...
        'VariableNames', {'Method','Deformation_mm','Force_kN'})];
writetable(damperFigureData, fullfile(figureDir, ...
    "adaptive_analysis_damper_hysteresis_comparison.csv"));
%%
%[text] ## Adaptive convergence history

[coarseNorm, coarseTolerance] = readConvergenceLog(adaptiveLog);

fig = figure(Color="w", Position=[100, 100, 820, 520]); %[output:91bb3e64]
ax = axes(fig); %[output:91bb3e64]
plotConvergenceHistory(ax, coarseNorm, coarseTolerance, ... %[output:91bb3e64]
    sprintf("$\\mathrm{Adaptive}\\ (\\Delta t=%.3f\\,\\mathrm{s})$", dtGM)); %[output:91bb3e64]

exportgraphics(fig, fullfile(figureDir, ... %[output:group:87a96ffd] %[output:91bb3e64]
    "adaptive_analysis_norm_history.pdf"), ContentType="vector"); %[output:group:87a96ffd] %[output:91bb3e64]
convergenceData = table((1:numel(coarseNorm)).', coarseNorm, ...
    coarseTolerance, ...
    'VariableNames', {'Attempt','Norm','Tolerance'});
writetable(convergenceData, fullfile(figureDir, ...
    "adaptive_analysis_norm_history.csv"));
%%
%[text] ## Local functions

function result = runAnalysis( ...
    ops, gmFile, dtGM, excitationScale, ...
    analysisType, nSteps, dt, outputDir, logFile)
%RUNANALYSIS Build and analyze one copy of the frame.

    buildFrameModel( ...
        ops, gmFile, dtGM, excitationScale);

    displacementFile = fullfile( ...
        outputDir, "roof_displacement.out");

    deformationFile = fullfile( ...
        outputDir, "damper_deformation.out");

    forceFile = fullfile( ...
        outputDir, "damper_force.out");

    deleteIfPresent({
        displacementFile
        deformationFile
        forceFile
    });

    ops.recorder( ...
        "Node", ...
        "-file", char(displacementFile), ...
        "-time", ...
        "-node", 4, ...
        "-dof", 1, ...
        "disp");

    ops.recorder( ...
        "Element", ...
        "-file", char(deformationFile), ...
        "-time", ...
        "-ele", 4, ...
        "deformations");

    ops.recorder( ...
        "Element", ...
        "-file", char(forceFile), ...
        "-time", ...
        "-ele", 4, ...
        "localForce");

    ops.wipeAnalysis();
    ops.constraints("Transformation");
    ops.numberer("RCM");
    ops.system("UmfPack");

    % The coarse adaptive case uses a deliberately small baseline iteration
    % limit to exercise recovery. Both fine-step cases use 200 iterations.
    tol = 1.0e-12;
    ops.algorithm("KrylovNewton");
    ops.integrator("Newmark", 0.5, 0.25);

    analysisType = lower(string(analysisType));
    switch analysisType
        case "adaptive"
            ops.test("EnergyIncr", tol, 5, 0);
        case {"reference", "adaptive_fine"}
            ops.test("EnergyIncr", tol, 200, 0);
        otherwise
            error('Unknown analysis type: "%s".', analysisType);
    end

    % The convergence test must be configured before the analysis object is
    % created; otherwise the new analysis can retain the preceding test.
    ops.analysis("Transient");

    timer = tic;

    switch analysisType
        case "reference"
            code = ops.analyze(nSteps, dt);

        case "adaptive"
            code = ops.adaptiveAnalyze( ...
                nSteps, dt, ...
                "-iterations", 4.0, 200, ...
                "-algorithms", ...
                    "NewtonLineSearch", ...
                    "Newton", ...
                "-subdivision", ...
                    0.5, dt/256.0, 10, ...
                "-limits", 1000, ...
                "-log", logFile);

        case "adaptive_fine"
            code = ops.adaptiveAnalyze(nSteps, dt);
    end

    runtime = toc(timer);
    endTime = ops.getTime();

    % wipe closes and flushes the recorders.
    ops.wipe();

    displacementData = readRecorder( ...
        displacementFile);

    deformationData = readRecorder( ...
        deformationFile);

    forceData = readRecorder( ...
        forceFile);

    result = struct();
    result.code = double(code);
    result.runtime = runtime;
    result.endTime = double(endTime);

    result.time = displacementData(:, 1);
    result.displacement = displacementData(:, 2);

    result.damperTime = deformationData(:, 1);
    result.damperDeformation = deformationData(:, 2);

    % The first local-force component has the opposite sign to the damper
    % deformation convention used for the hysteresis plot.
    result.damperForce = -forceData(:, 2);

    result = prependInitialState(result);
end

function buildFrameModel( ...
    ops, gmFile, dtGM, excitationScale)
%BUILDFRAMEMODEL Construct the nonlinear frame and excitation.

    ops.wipe();
    ops.model("BasicBuilder", "-ndm", 2, "-ndf", 3);

    bayWidth = 5000.0;
    storyHeight = 3000.0;

    ops.node(1, 0.0, 0.0);
    ops.node(2, bayWidth, 0.0);
    ops.node(3, 0.0, storyHeight);
    ops.node(4, bayWidth, storyHeight);

    ops.fix(1, 1, 1, 1);
    ops.fix(2, 1, 1, 1);

    ops.equalDOF(3, 4, 2, 3);

    weight = 1000.0;
    gravityAcceleration = 9810.0;
    floorMass = weight/gravityAcceleration;

    ops.mass(3, 0.5*floorMass, 0.0, 0.0);
    ops.mass(4, 0.5*floorMass, 0.0, 0.0);
%%
%[text] ## Column material

    steelTag = 1;
    yieldStress = 0.345;
    elasticModulus = 200.0;
    ultimateStress = 1.20*yieldStress;

    ops.uniaxialMaterial( ...
        "Steel4", ...
        steelTag, ...
        yieldStress, ...
        elasticModulus, ...
        "-kin", ...
        0.01, ...
        18.0, ...
        0.925, ...
        0.15, ...
        "-ult", ...
        ultimateStress, ...
        20.0);
%%
%[text] ## Column fiber section

    sectionTag = 1;

    depth = 300.0;
    webThickness = 8.0;
    flangeWidth = 220.0;
    flangeThickness = 14.0;

    yTop = 0.5*depth;
    yBottom = -0.5*depth;

    zLeft = -0.5*flangeWidth;
    zRight = 0.5*flangeWidth;

    zWebLeft = -0.5*webThickness;
    zWebRight = 0.5*webThickness;

    yTopFlangeBottom = ...
        0.5*depth - flangeThickness;

    yBottomFlangeTop = ...
        -0.5*depth + flangeThickness;

    ops.section("Fiber", sectionTag);

    ops.patch( ...
        "rect", steelTag, ...
        2, 12, ...
        yTopFlangeBottom, zLeft, ...
        yTop, zRight);

    ops.patch( ...
        "rect", steelTag, ...
        16, 2, ...
        yBottomFlangeTop, zWebLeft, ...
        yTopFlangeBottom, zWebRight);

    ops.patch( ...
        "rect", steelTag, ...
        2, 12, ...
        yBottom, zLeft, ...
        yBottomFlangeTop, zRight);
%%
%[text] ## Elastic roof beam

    beamDepth = 500.0;
    beamWebThickness = 12.0;
    beamFlangeWidth = 300.0;
    beamFlangeThickness = 20.0;

    beamArea = ...
        2.0*beamFlangeWidth*beamFlangeThickness + ...
        beamWebThickness* ...
        (beamDepth - 2.0*beamFlangeThickness);

    beamInertia = ...
        beamWebThickness* ...
        (beamDepth - 2.0*beamFlangeThickness)^3/12.0 + ...
        2.0*( ...
            beamFlangeWidth*beamFlangeThickness^3/12.0 + ...
            beamFlangeWidth*beamFlangeThickness* ...
            ((beamDepth - beamFlangeThickness)/2.0)^2);

    beamArea = 10.0*beamArea;
    beamInertia = 10.0*beamInertia;
%%
%[text] ## Nonlinear viscous damper

    damperTag = 10;

    ops.uniaxialMaterial( ...
        "ViscousDamper", ...
        damperTag, ...
        25.0, ...
        20.7452, ...
        0.35);
%%
%[text] ## Elements

    transformationTag = 1;
    integrationTag = 1;

    ops.geomTransf( ...
        "Linear", transformationTag);

    ops.beamIntegration( ...
        "Lobatto", ...
        integrationTag, ...
        sectionTag, ...
        5);

    ops.element( ...
        "forceBeamColumn", ...
        1, 1, 3, ...
        transformationTag, ...
        integrationTag);

    ops.element( ...
        "forceBeamColumn", ...
        2, 2, 4, ...
        transformationTag, ...
        integrationTag);

    ops.element( ...
        "elasticBeamColumn", ...
        3, 3, 4, ...
        beamArea, ...
        elasticModulus, ...
        beamInertia, ...
        transformationTag);

    ops.element( ...
        "twoNodeLink", ...
        4, 1, 4, ...
        "-mat", damperTag, ...
        "-dir", 1);
%%
%[text] ## Ground motion and damping

    ops.timeSeries( ...
        "Path", ...
        1, ...
        "-dt", dtGM, ...
        "-filePath", char(gmFile), ...
        "-factor", excitationScale);

    eigenvalue = ops.eigen(1);
    circularFrequency = sqrt(eigenvalue(1));

    dampingRatio = 0.02;

    ops.rayleigh( ...
        2.0*dampingRatio*circularFrequency, ...
        0.0, ...
        0.0, ...
        0.0);

    ops.pattern( ...
        "UniformExcitation", ...
        1, ...
        1, ...
        "-accel", ...
        1);
end

function result = prependInitialState(result)
%PREPENDINITIALSTATE Add the undeformed state at time zero.

    if isempty(result.time)
        result.time = 0.0;
        result.displacement = 0.0;
    elseif result.time(1) > 1.0e-12
        result.time = [0.0; result.time];
        result.displacement = ...
            [0.0; result.displacement];
    end

    if isempty(result.damperTime)
        result.damperTime = 0.0;
        result.damperDeformation = 0.0;
        result.damperForce = 0.0;
    elseif result.damperTime(1) > 1.0e-12
        result.damperTime = ...
            [0.0; result.damperTime];

        result.damperDeformation = ...
            [0.0; result.damperDeformation];

        result.damperForce = ...
            [0.0; result.damperForce];
    end
end

function interpolated = interpolateResponse( ...
    result, queryTime)
%INTERPOLATERESPONSE Evaluate responses at common physical times.

    queryTime = queryTime(:);

    if isempty(result.time)
        error("The analysis produced no displacement response.");
    end

    if queryTime(end) > result.endTime + 1.0e-9
        error( ...
            "Requested time %.6f s exceeds completed time %.6f s.", ...
            queryTime(end), result.endTime);
    end

    interpolated = struct();
    interpolated.time = queryTime;

    interpolated.displacement = interp1( ...
        result.time, ...
        result.displacement, ...
        queryTime, ...
        "linear");

    interpolated.damperDeformation = interp1( ...
        result.damperTime, ...
        result.damperDeformation, ...
        queryTime, ...
        "linear");

    interpolated.damperForce = interp1( ...
        result.damperTime, ...
        result.damperForce, ...
        queryTime, ...
        "linear");
end

function data = readRecorder(filename)
%READRECORDER Read an OpenSees text recorder.

    if ~isfile(filename)
        data = zeros(0, 2);
        return;
    end

    info = dir(filename);

    if isempty(info) || info.bytes == 0
        data = zeros(0, 2);
        return;
    end

    data = readmatrix( ...
        filename, ...
        FileType="text");

    if isempty(data)
        data = zeros(0, 2);
        return;
    end

    data = data(all(isfinite(data), 2), :);

    if ~isempty(data) && size(data, 2) < 2
        error( ...
            'Recorder file has fewer than two columns: "%s".', ...
            filename);
    end
end

function deleteIfPresent(files)
%DELETEIFPRESENT Remove files left by an earlier run.

    for i = 1:numel(files)
        filename = files{i};

        if isfile(filename)
            delete(filename);
        end
    end
end

function [lastNorm, tolerance] = readConvergenceLog(logFile)
%READCONVERGENCELOG Read real convergence attempts from an adaptive log.

    if ~isfile(logFile)
        error('Adaptive log was not created: "%s".', logFile);
    end

    history = readtable(logFile, ...
        TextType="string", VariableNamingRule="preserve");

    % Stage 3 rows describe subdivision events and do not run a test.
    if ismember("stageID", string(history.Properties.VariableNames))
        stage = history.stageID;
    else
        stage = history.stage;
    end
    attempts = history(stage ~= 3, :);
    lastNorm = abs(double(attempts.lastNorm));
    tolerance = double(attempts.tolerance);
    valid = isfinite(lastNorm) & isfinite(tolerance) & tolerance > 0;
    lastNorm = lastNorm(valid);
    tolerance = tolerance(valid);

    if isempty(lastNorm)
        error('No convergence-test results were found in "%s".', logFile);
    end

    lastNorm(lastNorm <= 0) = min(tolerance)*1.0e-8;
end

function plotConvergenceHistory(ax, lastNorm, tolerance, titleText)
%PLOTCONVERGENCEHISTORY Plot one point for each real analysis attempt.

    stepIndex = (1:numel(lastNorm)).';
    semilogy(ax, stepIndex, lastNorm, "b-", LineWidth=0.75, ...
        DisplayName="$\mathrm{Last\ norm}$");
    hold(ax, "on");
    semilogy(ax, stepIndex, tolerance, "r--", LineWidth=1.5, ...
        DisplayName="$\mathrm{Test\ tolerance}$");

    xlim(ax, [0, max(stepIndex)]);
    allValues = [lastNorm; tolerance];
    ylim(ax, [10^floor(log10(min(allValues))), ...
        10^ceil(log10(max(allValues)))]);

    set(ax, FontName="Arial", FontSize=15, LineWidth=1.0, ...
        TickDir="out", XGrid="on", YGrid="on", YMinorGrid="on", ...
        GridLineStyle="-", GridAlpha=0.18, MinorGridLineStyle=":", ...
        MinorGridAlpha=0.18, TickLabelInterpreter="latex");
    xlabel(ax, "$\mathrm{Attempt\ index}$", ...
        Interpreter="latex", FontSize=17);
    ylabel(ax, "$\mathrm{Last\ norm}$", ...
        Interpreter="latex", FontSize=17);
    title(ax, titleText, Interpreter="latex", FontSize=17);
    legend(ax, Location="best", Box="on", Color="white", ...
        EdgeColor=[0.35 0.35 0.35], Interpreter="latex", FontSize=14);
end

function stylePaperAxes(ax)
%STYLEPAPERAXES Apply publication-oriented formatting.

    set(ax, ...
        FontName="Arial", ...
        FontSize=15, ...
        LineWidth=1.0, ...
        TickDir="out", ...
        GridLineStyle="--", ...
        GridAlpha=0.20, ...
        MinorGridAlpha=0.10, ...
        Box="on", ...
        TickLabelInterpreter="latex");

    ax.XMinorGrid = "on";
    ax.YMinorGrid = "on";
    ax.LabelFontSizeMultiplier = 1.15;
    ax.TitleFontSizeMultiplier = 1.15;
end

